const STOP = new Set('il lo la i gli le un uno una di a da in con su per tra fra e o ma che mi ti ci vi si ne non al allo alla ai agli alle dal dallo dalla dai dagli dalle del dello della dei degli delle nel nello nella nei negli nelle sul sullo sulla sui sugli sulle col mio mia miei mie tuo tua suo sua questo questa quello quella è sono sto c l d un po più piu anche poi molto proprio posso puo puoi voglio vorrei devo dovrei fare fa serve app applicazione lifepilot theia'.split(' '));
const SYN: Record<string, string> = {};
