const norm = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9&\s]/g, ' ').replace(/\s+/g, ' ').trim();
const stem = (w: string) => (w.length > 6 ? w.slice(0, 6) : w);
/** Parole significative di una domanda: senza articoli, con i sinonimi unificati e le parole ridotte alla radice. */
export function faqTokens(s: string): string[] {
  return norm(s).split(' ').filter((w) => w && !STOP.has(w)).map((w) => SYN[w] ?? w).map(stem).filter((w, i, a) => a.indexOf(w) === i);
}

export type FaqHit = { faq: Faq; question: string; score: number; hits: number };
/** Quante parole della domanda-tipo ci sono nella tua frase e quanto la copre (0-1: conta quanto la domanda è contenuta nella tua frase e viceversa). */
export function scoreFaq(user: string[], question: string): { score: number; hits: number } {
  const q = faqTokens(question);
  if (q.length < 2 || !user.length) return { score: 0, hits: 0 };
  const hits = q.filter((t) => user.some((u) => u === t || (u.length >= 4 && t.length >= 4 && (u.startsWith(t) || t.startsWith(u))))).length;
  const cov = hits / q.length, prec = hits / user.length;
  // ok se copre quasi tutta la domanda-tipo; oppure se almeno tre parole combaciano e due terzi della domanda sono presenti
  if (!(cov >= 0.75 || (hits >= 3 && cov >= 0.6))) return { score: 0, hits };
  return { score: Math.round((cov * 0.7 + prec * 0.3) * 1000) / 1000, hits };
}
/** La risposta che combacia meglio (null = nessuna abbastanza sicura): prima chi ha più parole in comune, poi chi copre meglio. */
export function matchFaq(text: string): FaqHit | null {
  const user = faqTokens(text);
  if (user.length < 2) return null;
  let best: FaqHit | null = null;
  for (const faq of FAQ) for (const question of faq.questions) {
    const { score, hits } = scoreFaq(user, question);
    if (score <= 0 || (hits < 3 && score < 0.78)) continue;
    const better = !best || hits > best.hits || (hits === best.hits && (score > best.score || (score === best.score && faqTokens(question).length > faqTokens(best.question).length)));
    if (better) best = { faq, question, score, hits };
  }
  return best;
}
export const FAQ_COUNT = FAQ.reduce((a, f) => a + f.questions.length, 0);
